ACTION=$(echo -e "Connect\nDisconnect\nReconnect" | fzf --prompt="Mullvad Action > ") && case $ACTION in "Connect") MAP=$(mullvad relay list | awk '{v=$1; sub(/,$/,"",v); if(v~/-.*-/){if(p!=""){ci=p;p=""}; print co":"ci":"v} else {if(p!=""){co=p}; p=v}}') && CAT=$(echo "$MAP" | awk -F':' '{print $1"\n"$2}' | sort -u | fzf --prompt="Country/City > ") && [ -n "$CAT" ] && SRV=$(echo "$MAP" | awk -F':' -v c="$CAT" '$1==c || $2==c {print $3}' | fzf --prompt="Server in $CAT > ") && [ -n "$SRV" ] && mullvad relay set location "$SRV" && mullvad connect ;; "Disconnect") mullvad disconnect ;; "Reconnect") mullvad reconnect ;; esac
